pub(super) fn for_path(path: &str) -> &'static Icon {
    if path
        .rsplit('/')
        .next()
        .is_some_and(|name| name.starts_with("nuxt.config."))
    {
        return &NUXT;
    }
    let ext = path.rsplit('.').next().unwrap_or("").to_ascii_lowercase();
    match ext.as_str() {
        "vue" => &VUE,
        "ts" => &TS,
        "tsx" => &REACT_TS,
        "js" | "mjs" | "cjs" => &JS,
        "jsx" => &REACT_JS,
        "rs" => &RUST,
        "json" => &JSON,
        "md" => &MD,
        "mdx" => &MDX,
        "html" => &HTML,
        "css" => &CSS,
        "py" => &PY,
        "svelte" => &SVELTE,
        _ => &DEFAULT,
    }
}
